def rules():
    return dict(RULES)

def subtotal(lines):
    amount = 0
    count = 0
    for line in lines:
        if type(line.quantity) is not int or line.quantity < 1:
            raise ValueError('quantity must be a positive integer seat count')
        if type(line.unit_cents) is not int or line.unit_cents < 0:
            raise ValueError('unit_cents')
        amount += line.unit_cents * line.quantity
        count += 1
    return amount, count

