from dataclasses import dataclass
from pricing import rules, subtotal

@dataclass(frozen=True)
class Line:
    sku: str
    unit_cents: int
    quantity: int

def quote(lines, region):
    if region not in {'domestic', 'international'}:
        raise ValueError('region')
    amount, count = subtotal(lines)
    policy = rules()
    shipping = 0 if not count else policy['international_cents'] if region == 'international' else 0 if amount >= policy['free_threshold'] else policy['domestic_cents']
    return {'subtotal_cents': amount, 'shipping_cents': shipping, 'total_cents': amount + shipping}

